const $=s=>document.querySelector(s);
const esc=s=>String(s??"").replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
const P=Object.fromEntries(D.providers.map(p=>[p.code,p]));
const R=Object.fromEntries(D.refs.map(r=>[r.i,r]));
const SN=D.strands;
const plink=c=>{const p=P[c];return p?`<a href="${esc(p.url)}" target="_blank" rel="noopener">${esc(p.name)}</a> <span class="code">${c}</span>`:`<span class="code">${esc(c)}</span>`};
const TXT={T01:"Principles of Management",T02:"Organizational Behavior",T03:"Principles of Marketing",T04:"Principles of Accounting 1",T05:"Principles of Accounting 2",T06:"Principles of Finance",T07:"Introductory Business Statistics",T09:"Entrepreneurship",T10:"Business Ethics",T12:"Business Law Essentials",T13:"Introduction to Intellectual Property",T14:"Foundations of Information Systems",T15:"Principles of Data Science",T16:"Workplace Software and Skills",T17:"Open Textbook Library",T18:"LibreTexts Business",T19:"BCcampus Open Collection",T20:"Saylor Academy business courses",B06:"OECD publications",C04:"GRI Standards",D01:"World Bank Open Data",D06:"WTO Stats",D07:"ILOSTAT",D09:"Our World in Data",D11:"IEA data",D15:"Company filings (EDGAR)",D19:"Global Entrepreneurship Monitor",D20:"World Values Survey",D21:"Corruption Perceptions Index",D22:"Open data sets",D23:"Dataset search",N05:"Ministry of Statistics",N06:"Open Government Data India",N08:"Stock exchange filings",C01:"Company filings as live cases",C07:"Corporate governance principles"};
const lbl=c=>P[c]?plink(c):`${esc(TXT[c]||c)} <span class="code">${c}</span>`;

// stats
const pubProv=D.providers.length;
$("#stats").innerHTML=[[D.refs.length,"references in the public register"],[pubProv,"libraries, courses and collections"],[D.programmes.length,"programmes enriched"],[D.ladders.length,"career ladders linked"],[D.emba.length,"EMBA courses backed"]].map(([n,t])=>`<div><b>${n}</b><span>${t}</span></div>`).join("");

// pipeline
const PIPE=[["1 Gather","Books, syllabi and bibliographies are collected from HFL's library, partner shelves and public sources.","Source list with status"],["2 Extract","Reference lists are pulled from each book's bibliography, notes and further reading.","Raw citations"],["3 Clean and tag","Duplicates are merged. Each title is tagged by strand, level, era and access.","Register entry with an ID"],["4 Find an open copy","Each title is matched to a public library, open textbook or open course. Paid titles are marked for licence.","Access route"],["5 Map","Titles are attached to units, programmes, EMBA courses and career ladders.","Reading shelf per unit"],["6 Review","Two assessors check fit, level and freshness. Old figures are refreshed before use.","Approved shelf"],["7 Publish","Shelves go live in lessons and in the HFL library.","Unit version"],["8 Learn from use","Usage and drop-off signals return to authors each quarter.","Change requests"]];
$("#pipe").innerHTML=PIPE.map(r=>`<tr><td><b>${r[0]}</b></td><td>${r[1]}</td><td>${r[2]}</td></tr>`).join("");

// tiers
$("#tiers").innerHTML=D.tiers.map(t=>`<div class="tier"><div><small>${esc(t.tier)}</small><b>${esc(t.award)}</b></div><p>${esc(t.rule)}</p><code>${esc(t.sources)}</code></div>`).join("");

// tabs
const tabs=[...document.querySelectorAll('#tabs button')];
function showTab(b){tabs.forEach(x=>{const on=x===b;x.setAttribute("aria-selected",on);document.getElementById(x.getAttribute("aria-controls")).hidden=!on});try{localStorage.setItem("hfl-ri-tab",b.id)}catch(e){}}
tabs.forEach(b=>b.addEventListener("click",()=>showTab(b)));
try{const t=localStorage.getItem("hfl-ri-tab");if(t&&document.getElementById(t))showTab(document.getElementById(t))}catch(e){}

const strandOpts=(all)=>`<option value="">${all}</option>`+Object.entries(SN).map(([k,v])=>`<option value="${k}">${k} · ${esc(v)}</option>`).join("");

// programmes
$("#sProg").innerHTML=strandOpts("All strands");
let progLimit=20;
function drawProg(){
  const q=$("#qProg").value.toLowerCase(),s=$("#sProg").value,l=$("#lProg").value;
  const rows=D.programmes.filter(p=>(!s||p.strand===s)&&(!l||p.level===l)&&(!q||(p.title+" "+p.careers+" "+p.svc+" "+p.code).toLowerCase().includes(q)));
  $("#cProg").textContent=`${rows.length} of ${D.programmes.length}`;
  $("#progList").innerHTML=rows.slice(0,progLimit).map(p=>`<details class="row"><summary><div><b>${esc(p.title)}</b><div class="code">${p.code} · ${p.ects} ECTS · ${esc(p.careers)}</div></div><div class="chips"><span class="k">${p.strand}</span><span class="k">${p.level}</span></div></summary><div class="inner">
    <div><h4>Core open text</h4><ul>${p.core_text.map(c=>`<li>${lbl(c)}</li>`).join("")}</ul></div>
    <div><h4>Open courses</h4><ul>${p.open_courses.map(c=>`<li>${plink(c)}</li>`).join("")}</ul></div>
    <div><h4>Libraries</h4><ul>${p.libraries.map(c=>`<li>${plink(c)}</li>`).join("")}</ul></div>
    <div><h4>Live data</h4><ul>${p.data.map(c=>`<li>${lbl(c)}</li>`).join("")}</ul></div>
    <div><h4>Classic readings</h4><ul>${p.theory.map(i=>R[i]?`<li>${esc(R[i].t)} (${R[i].y}) <span class="code">${i}</span></li>`:"").join("")}</ul></div>
    <div><h4>Books</h4><ul>${p.books.map(i=>R[i]?`<li>${esc(R[i].t)} <span class="code">${i} · ${esc(R[i].l)}</span></li>`:"").join("")}</ul></div>
    <div class="earn"><b>Earn:</b> ${esc(p.svc)}. <b>Author bank:</b> ${p.outputs.slice(0,6).map(esc).join(", ")}.</div>
  </div></details>`).join("")||"<p>No programmes match. Clear the search or pick another strand.</p>";
  $("#moreProg").hidden=rows.length<=progLimit;
}
["qProg","sProg","lProg"].forEach(id=>$("#"+id).addEventListener("input",()=>{progLimit=20;drawProg()}));
$("#moreProg").addEventListener("click",()=>{progLimit+=20;drawProg()});
drawProg();

// ladders
$("#ladBody").innerHTML=D.ladders.map(l=>`<tr><td><b>${esc(l.name)}</b><div class="code">${l.code}</div></td><td>${l.strand}</td><td>${l.providers.map(plink).join("<br>")}</td>${Object.values(l.rung_libraries).map(v=>`<td>${v.map(c=>`<span class="code">${c}</span>`).join(" ")}</td>`).join("")}</tr>`).join("");

// emba
$("#embaBody").innerHTML=D.emba.map(e=>`<tr><td class="code">${e.code}</td><td>${esc(e.title)}</td><td class="num">${e.theory_refs}</td><td class="num">${e.course_books}</td></tr>`).join("");

// providers
const uniq=a=>[...new Set(a)].sort();
$("#tProv").innerHTML=`<option value="">All types</option>`+uniq(D.providers.map(p=>p.kind)).map(k=>`<option>${esc(k)}</option>`).join("");
$("#rProv").innerHTML=`<option value="">All regions</option>`+uniq(D.providers.map(p=>p.region)).map(k=>`<option>${esc(k)}</option>`).join("");
function drawProv(){
  const q=$("#qProv").value.toLowerCase(),t=$("#tProv").value,r=$("#rProv").value,v=$("#vProv").value;
  const rows=D.providers.filter(p=>(!t||p.kind===t)&&(!r||p.region===r)&&(!v||p.levels.includes(v))&&(!q||(p.name+" "+p.note).toLowerCase().includes(q)));
  $("#cProv").textContent=`${rows.length} of ${D.providers.length}`;
  $("#provBody").innerHTML=rows.map(p=>`<tr><td class="code">${p.code}</td><td><a href="${esc(p.url)}" target="_blank" rel="noopener">${esc(p.name)}</a></td><td>${esc(p.kind)}</td><td class="code">${p.levels.join(" ")}</td><td>${esc(p.region)} · ${esc(p.lang)}</td><td>${esc(p.note)}</td></tr>`).join("");
}
["qProv","tProv","rProv","vProv"].forEach(id=>$("#"+id).addEventListener("input",drawProv));
drawProv();

// register
$("#sRef").innerHTML=strandOpts("All strands");
$("#eRef").innerHTML=`<option value="">All eras</option>`+uniq(D.refs.map(r=>r.e)).map(k=>`<option>${esc(k)}</option>`).join("");
$("#oRef").innerHTML=`<option value="">All sources</option>`+uniq(D.refs.map(r=>r.src)).map(k=>`<option>${esc(k)}</option>`).join("");
let refLimit=60;
function drawRef(){
  const q=$("#qRef").value.toLowerCase(),s=$("#sRef").value,e=$("#eRef").value,o=$("#oRef").value;
  const rows=D.refs.filter(r=>(!s||r.s.includes(s))&&(!e||r.e===e)&&(!o||r.src===o)&&(!q||r.t.toLowerCase().includes(q)));
  $("#cRef").textContent=`${rows.length} of ${D.refs.length}`;
  const cls=l=>/open|public/i.test(l)?"ok":/licen/i.test(l)?"lic":"wait";
  $("#refBody").innerHTML=rows.slice(0,refLimit).map(r=>`<tr><td class="code">${r.i}</td><td>${esc(r.t)}<div class="code">${esc(r.k)} · ${esc(r.e)}${r.tp?" · "+esc(r.tp)+" · "+esc(r.rg)+" · "+esc(r.ld):""}</div></td><td class="num">${r.y??""}</td><td class="code">${r.s.join(" ")}</td><td class="code">${r.c.join(" ")}</td><td><span class="pill ${cls(r.l)}">${esc(r.l)}</span></td></tr>`).join("");
  $("#moreRef").hidden=rows.length<=refLimit;
}
["qRef","sRef","eRef","oRef"].forEach(id=>$("#"+id).addEventListener("input",()=>{refLimit=60;drawRef()}));
$("#moreRef").addEventListener("click",()=>{refLimit+=60;drawRef()});
drawRef();

// sources
const scls=s=>/read|reused|added/i.test(s)?"ok":"wait";
$("#srcBody").innerHTML=D.sources.map(s=>`<tr><td><b>${esc(s[0])}</b></td><td><span class="pill ${scls(s[1])}">${esc(s[1])}</span></td><td class="num">${s[2]||"—"}</td><td>${esc(s[3])}</td></tr>`).join("");
